t\\t\\t\\tvar date = now.getDate();\\r\\n\\t\\t\\t\\tvar hour = now.getHours();\\r\\n\\t\\t\\t\\tvar minute = now.getMinutes();\\r\\n\\t\\t\\t\\tvar second = now.getSeconds();\\r\\n\\t\\t\\t\\treturn PrefixInteger(date, 2) + \\"日 \\" + PrefixInteger(hour, 2) + \\"时\\"+PrefixInteger(minute, 2) + \\"分\\";;\\r\\n\\r\\n\\t\\t\\t}\\r\\n\\t\\t\\tfunction PrefixInteger(num, n) {\\r\\n\\t\\t\\t\\treturn(Array(n).join(0) + num).slice(-n);\\r\\n\\t\\t\\t}\\r\\n\\r\\nwindow.addEventListener('message',function(rs){\\r\\n    var pointdata=rs.data;\\r\\nif(pointdata=='refresh'){\\r\\n     window.location.reload();\\r\\n}else{\\r\\nconsole.log(pointdata);\\r\\n}\\r\\n})\\r\\n</script>\\r\\n\\t</body>\\r\\n\\r\\n</html>\\r\\n","headers":{"X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Sat, 10 Oct 2026 10:30:21 GMT","Server":"nginx","Set-Cookie":"WJSESSIONID=5458D5F3C82851F459228A85ECFE9AE6; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.239; local=123.58.10.239:29534; remote=219.140.196.72:80"}}	reczz28LfvIwAkfc
