na1k58ggqm7	na1k58ggqm7	{"parentId":"ails1kyi44d","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT v.scenario_name, '今天价值' AS item, round(v.value_today::numeric, 2) AS price, v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '600900.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '低档关注价', round(v.watch_low::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '600900.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '高档关注价', round(v.watch_high::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '600900.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '市场价', round(v.market_price::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '600900.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY sort, item"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"scenario_name","yField":"price","seriesField":"item"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.watch"},"cardSettings":{"titleDescription":{"title":"图表 · 今天价值、关注价与市场价（元）"}}}}
