wd9kgxxqm42	wd9kgxxqm42	{"parentId":"ails1kyi44d","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT h.year::text AS year, '历史' AS kind, round(h.interest_debt::numeric, 0) AS debt FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '600900.SH' WHERE h.interest_debt IS NOT NULL UNION ALL SELECT f.year::text, '预测', round(fc.debt_close::numeric, 0) FROM vi_forecast_base f JOIN vi_forecast_calc fc USING (id) JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '600900.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY year"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"year","yField":"debt","seriesField":"kind"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.debt"},"cardSettings":{"titleDescription":{"title":"图表 · 带息负债：历史与预测（亿元）"}}}}
nzmhj4s1ptb	nzmhj4s1ptb	{"parentId":"ails1kyi44d","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '600900.SH' CROSS JOIN LATERAL (VALUES ('归母净利润', h.np_parent), ('分红总额', h.dividend_total)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"year","yField":"amount","seriesField":"item"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.hist_np"},"cardSettings":{"titleDescription":{"title":"图表 · 历史：归母净利润与分红总额（亿元）"}}}}
