zepxcjaoa3f	zepxcjaoa3f	{"parentId":"d7pqv49jcrp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT s.scenario_name AS \\"情景\\", x.k AS \\"部分\\", round((x.v / s.shares)::numeric, 2) AS \\"元/股\\", s.id, x.o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('核心业务', s.core_value, 1), ('成熟业务', s.mature_value, 2), ('成长业务', s.growth_value, 3), ('投入期业务', s.invest_value, 4), ('直接估值业务', s.direct_value, 4), ('可用净现金', s.usable_net_cash, 5), ('对外投资（折后）', s.investments, 6), ('少数股东与其他', s.minority_other, 7), ('合计', s.equity_value, 8)) x(k, v, o) WHERE x.v IS NOT NULL ORDER BY s.id, x.o"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"情景","yField":"元/股","seriesField":"部分"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.sotp_parts"},"cardSettings":{"titleDescription":{"title":"分部加总：每股价值构成（元）"}}}}
b6z5kgkegh2	b6z5kgkegh2	{"parentId":"d7pqv49jcrp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT g.name AS \\"部分\\", round((g.value / s.shares)::numeric, 2) AS \\"元/股\\", 10 + coalesce(nullif(regexp_replace(g.code, '\\\\D', '', 'g'), '')::int, 0) AS o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' JOIN vi_sotp_segment_val g ON g.scenario_id = s.id WHERE s.is_base UNION ALL SELECT '核心业务', round((s.core_value / s.shares)::numeric, 2), 1 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' WHERE s.is_base AND s.core_value IS NOT NULL UNION ALL SELECT x.k, round((x.v / s.shares)::numeric, 2), x.o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('可用净现金', s.usable_net_cash, 30), ('对外投资（折后）', s.investments, 31), ('少数股东与其他', s.minority_other, 32), ('每股价值', s.equity_value, 40), ('市场价', s.market_price * s.shares, 41)) x(k, v, o) WHERE s.is_base AND x.v IS NOT NULL ORDER BY 3"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"部分","yField":"元/股"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.sotp_bridge"},"cardSettings":{"titleDescription":{"title":"分部加总：基准情景价值构成（元/股，逐项）"}}}}
o71ohcwn9y1	o71ohcwn9y1	{"parentId":"d7pqv49jcrp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT x.m AS \\"倍数\\", s.scenario_name AS \\"系列\\", round(((coalesce(s.core_earnings, 0) * x.m + coalesce(s.mature_earn_pv, 0) * x.m + coalesce(s.mature_interim_pv, 0) + coalesce(s.growth_value, 0) + coalesce(s.invest_value, 0) + coalesce(s.direct_value, 0) + s.noncore) / s.shares)::numeric, 2) AS \\"每股价值\\", s.id FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN generate_series(4, 24, 2) x(m) UNION ALL SELECT x.m, '市场价', round(s.market_price::numeric, 2), 999 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN generate_series(4, 24, 2) x(m) WHERE s.is_base ORDER BY 1, 4"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"倍数","yField":"每股价值","seriesField":"系列"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.sotp_grid"},"cardSettings":{"titleDescription":{"title":"分部加总：倍数 → 每股价值（元；核心业务或成熟业务的倍数）"}}}}
