cp5hgypbm7c	cp5hgypbm7c	{"parentId":"jsgkz08ee0b","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT x.price AS \\"买入价\\", '隐含收益率' AS \\"系列\\", round((vi_irr(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.price) * 100)::numeric, 2) AS \\"收益率\\" FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) UNION ALL SELECT x.price, '要求收益率', round((f.required_return * 100)::numeric, 2) FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) ORDER BY 1, 2"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"买入价","yField":"收益率","seriesField":"系列"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.irr_curve"},"cardSettings":{"titleDescription":{"title":"买入价 → 隐含年化收益率（基准情景，%）"}}}}
tuh1hrkvv8n	tuh1hrkvv8n	{"parentId":"jsgkz08ee0b","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT round((x.r * 100)::numeric, 1)::text || '%' AS \\"要求收益率\\", s.name AS \\"情景\\", round(vi_pv(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.r)::numeric, 2) AS \\"最高买入价\\", x.r, s.sort FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x UNION ALL SELECT round((x.r * 100)::numeric, 1)::text || '%', '市场价', round(cc.latest_price::numeric, 2), x.r, 99 FROM vi_model_base m JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x ORDER BY 4, 5"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"要求收益率","yField":"最高买入价","seriesField":"情景"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.req_curve"},"cardSettings":{"titleDescription":{"title":"要求收益率 → 最高买入价（元）"}}}}
