35h57hy00cz	35h57hy00cz	{"parentId":"jsgkz08ee0b","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT c.name AS \\"对手\\", x.k AS \\"指标\\", round((x.v * 100)::numeric, 1) AS \\"%\\" FROM vi_competitor_base c JOIN vi_company_base co ON co.id = c.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('付费率或渗透率', c.paying_rate), ('毛利率', c.gross_margin), ('增速', c.growth)) x(k, v) WHERE x.v IS NOT NULL UNION ALL SELECT co.name || '（本公司）', x.k, round((x.v * 100)::numeric, 1) FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('增速', hc.revenue_yoy)) x(k, v) WHERE x.v IS NOT NULL AND h.year = (SELECT max(h2.year) FROM vi_fin_history_base h2 WHERE h2.company_id = h.company_id) ORDER BY 1, 2"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"对手","yField":"%","seriesField":"指标"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.peers"},"cardSettings":{"titleDescription":{"title":"竞争对手对比（%）：付费率、毛利率、增速"}}}}
