hour = now.getHours();\\r\\n\\t\\t\\t\\tvar minute = now.getMinutes();\\r\\n\\t\\t\\t\\tvar second = now.getSeconds();\\r\\n\\t\\t\\t\\treturn PrefixInteger(date, 2) + \\"日 \\" + PrefixInteger(hour, 2) + \\"时\\"+PrefixInteger(minute, 2) + \\"分\\";;\\r\\n\\r\\n\\t\\t\\t}\\r\\n\\t\\t\\tfunction PrefixInteger(num, n) {\\r\\n\\t\\t\\t\\treturn(Array(n).join(0) + num).slice(-n);\\r\\n\\t\\t\\t}\\r\\n\\r\\nwindow.addEventListener('message',function(rs){\\r\\n    var pointdata=rs.data;\\r\\nif(pointdata=='refresh'){\\r\\n     window.location.reload();\\r\\n}else{\\r\\nconsole.log(pointdata);\\r\\n}\\r\\n})\\r\\n</script>\\r\\n\\t</body>\\r\\n\\r\\n</html>\\r\\n","headers":{"Set-Cookie":"WJSESSIONID=FDD981931E827D83B249F46BAFB8B6F6; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.238; local=123.58.10.238:34526; remote=219.140.196.72:80","X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Fri, 25 Sep 2026 10:30:14 GMT","Server":"nginx"}}	3	2026-10-21 21:23:27.860014+08	2026-10-21 21:23:27.860014+08	\N	\N
